create table if not exists public.public_content (id uuid primary key default gen_random_uuid(), content_key text not null, locale text not null check (locale in ('uk','en','it')), content jsonb not null default '{}'::jsonb, active boolean not null default true, updated_at timestamptz not null default now(), updated_by uuid references auth.users(id), unique (content_key,locale)); create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, target_type text not null, target_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()); alter table public.public_content enable row level security; alter table public.audit_logs enable row level security;